package com.ansh.bank.transaction.service;
import java.math.*; import java.time.*; import java.util.*; import com.ansh.bank.common.config.SeedData; import com.ansh.bank.common.exception.ApiException; import com.ansh.bank.transaction.dto.TransactionDtos.*; import org.springframework.stereotype.Service;
/** Process simulated customer transfers and history. */ @Service public class TransactionService {private final SeedData d; public TransactionService(SeedData d){this.d=d;} /** Return account movements. */ public List<Response> all(){return d.transactions.stream().map(t->new Response(t.id(),t.description(),t.amount(),t.direction(),t.date())).toList();} /** Validate and record an outgoing transfer. */ public synchronized Response transfer(TransferRequest r){if(r.amount()==null||r.amount().compareTo(BigDecimal.ZERO)<=0)throw new ApiException("Enter an amount greater than zero");var account=d.accounts.stream().filter(a->a.id().equals(r.accountId())).findFirst().orElseThrow(()->new ApiException("Account not found"));var payee=d.beneficiaries.stream().filter(b->b.id().equals(r.beneficiaryId())&&b.status().equals("VERIFIED")).findFirst().orElseThrow(()->new ApiException("Choose a verified beneficiary"));if(account.balance().compareTo(r.amount())<0)throw new ApiException("Insufficient funds");int i=d.accounts.indexOf(account);d.accounts.set(i,new SeedData.Account(account.id(),account.name(),account.number(),account.balance().subtract(r.amount()),account.type()));var tx=new SeedData.Tx("tx-"+UUID.randomUUID(),account.id(),"Transfer to "+payee.name(),r.amount(),"DEBIT",LocalDateTime.now());d.transactions.add(0,tx);return new Response(tx.id(),tx.description(),tx.amount(),tx.direction(),tx.date());} }
